		templ_7745c5c3_Err = templruntime.WriteString(templ_7745c5c3_Buffer, 25, "</a></div><!-- Mentions indicator: comments that @-mention the current user, not yet seen --><button @click=\"openMentions()\" type=\"button\" title=\"Comments mentioning you\" class=\"relative inline-flex items-center p-2 rounded-lg text-slate-600 dark:text-slate-400 hover:text-slate-900 dark:hover:text-white hover:bg-white/50 dark:hover:bg-slate-700/50 transition-colors\"><svg class=\"w-4 h-4\" fill=\"none\" viewBox=\"0 0 24 24\" stroke-width=\"2\" stroke=\"currentColor\"><path stroke-linecap=\"round\" stroke-linejoin=\"round\" d=\"M16.5 12a4.5 4.5 0 11-9 0 4.5 4.5 0 019 0zm0 0c0 1.657 1.007 3 2.25 3S21 13.657 21 12a9 9 0 10-2.636 6.364M16.5 12V8.25\"></path></svg> <span x-show=\"unseenCount > 0\" x-cloak x-text=\"unseenCount > 99 ? '99+' : unseenCount\" class=\"absolute -top-1 -right-1 inline-flex items-center justify-center min-w-[1.1rem] h-[1.1rem] px-1 rounded-full text-[10px] font-bold bg-red-500 text-white\"></span></button></nav><script>\n\t\t// Polls for unseen @mentions, shows a badge next to the Activity tab and raises the\n\t\t// browser notification for each new mention, on every page (this component is embedded\n\t\t// wherever PageNavigator is). Fetches its own current-user id via /api/v1/auth/profile\n\t\t// rather than threading one through every caller's page template - one extra cheap GET\n\t\t// per page load, in exchange for staying fully self-contained.\n\t\t//\n\t\t// Mention notifications are raised here rather than delegated to NotificationService:\n\t\t// that service is loaded by the dashboard page only, and even there it boots\n\t\t// asynchronously, so any hand-off is a race the first poll loses. Self-contained\n\t\t// delivery also makes the \"mentions ignore severity and filter-preset scoping\" rule\n\t\t// true by construction instead of by a bypass inside the alert pipeline.\n\t\tfunction mentionsWatcher() {\n\t\t\treturn {\n\t\t\t\tunseenCount: 0,\n\t\t\t\tuserId: null,\n\t\t\t\ttimer: null,\n\n\t\t\t\tinit() {\n\t\t\t\t\tthis.start();\n\t\t\t\t},\n\n\t\t\t\tasync start() {\n\t\t\t\t\ttry {\n\t\t\t\t\t\tconst response = await fetch('/api/v1/auth/profile', { credentials: 'include' });\n\t\t\t\t\t\tif (response.ok) {\n\t\t\t\t\t\t\tconst result = await response.json();\n\t\t\t\t\t\t\tif (result.success && result.data?.user?.id) {\n\t\t\t\t\t\t\t\tthis.userId = result.data.user.id;\n\t\t\t\t\t\t\t}\n\t\t\t\t\t\t}\n\t\t\t\t\t} catch (error) {\n\t\t\t\t\t\tconsole.error('Failed to load current user for mentions watcher:', error);\n\t\t\t\t\t}\n\t\t\t\t\tif (!this.userId) {\n\t\t\t\t\t\treturn;\n\t\t\t\t\t}\n\t\t\t\t\tawait this.poll();\n\t\t\t\t\tthis.timer = setInterval(() => this.poll(), 30000);\n\t\t\t\t},\n\n\t\t\t\tseenKey() {\n\t\t\t\t\treturn 'notificator_mention_seen_' + this.userId;\n\t\t\t\t},\n\n\t\t\t\tnotifiedKey() {\n\t\t\t\t\treturn 'notificator_mention_notified_' + this.userId;\n\t\t\t\t},\n\n\t\t\t\tasync poll() {\n\t\t\t\t\ttry {\n\t\t\t\t\t\tconst response = await fetch('/api/v1/dashboard/activity?mentionsOnly=true&windowMinutes=10080', {\n\t\t\t\t\t\t\tcredentials: 'include'\n\t\t\t\t\t\t});\n\t\t\t\t\t\tconst result = await response.json();\n\t\t\t\t\t\tif (!response.ok || !result.success) {\n\t\t\t\t\t\t\treturn;\n\t\t\t\t\t\t}\n\t\t\t\t\t\tconst events = result.data.events || [];\n\n\t\t\t\t\t\tconst seenAt = Number(localStorage.getItem(this.seenKey())) || 0;\n\t\t\t\t\t\tthis.unseenCount = events.filter(e => new Date(e.createdAt).getTime() > seenAt).length;\n\n\t\t\t\t\t\tawait this.notifyFresh(events);\n\t\t\t\t\t} catch (error) {\n\t\t\t\t\t\tconsole.error('Failed to poll mentions:', error);\n\t\t\t\t\t}\n\t\t\t\t},\n\n\t\t\t\t// The notified watermark is a delivery receipt, not a \"we looked at this poll\"\n\t\t\t\t// marker: it moves past a mention only once that mention has actually been\n\t\t\t\t// shown, or once we know the user asked not to be notified. Anything that\n\t\t\t\t// leaves delivery undecided (preferences unreachable) leaves the watermark\n\t\t\t\t// alone so the next poll retries, instead of consuming the mention silently.\n\t\t\t\t//\n\t\t\t\t// This component is instantiated once per open tab, and every instance reads\n\t\t\t\t// and writes the same localStorage watermark. Without coordination, two tabs\n\t\t\t\t// polling close together can both read the same stale watermark and both\n\t\t\t\t// notify for the same mention. navigator.locks scopes the read-decide-write\n\t\t\t\t// below to one tab at a time per user; browsers without the Web Locks API\n\t\t\t\t// fall back to running unlocked (the pre-existing, racy behavior).\n\t\t\t\tasync notifyFresh(events) {\n\t\t\t\t\tif ('locks' in navigator) {\n\t\t\t\t\t\tawait navigator.locks.request(this.notifiedKey(), () => this._notifyFresh(events));\n\t\t\t\t\t} else {\n\t\t\t\t\t\tawait this._notifyFresh(events);\n\t\t\t\t\t}\n\t\t\t\t},\n\n\t\t\t\tasync _notifyFresh(events) {\n\t\t\t\t\tconst notifiedAt = Number(localStorage.getItem(this.notifiedKey()));\n\t\t\t\t\t// First poll in this browser, or a corrupted watermark: start at \"now\" so a\n\t\t\t\t\t// pre-existing backlog doesn't fire a burst of notifications.\n\t\t\t\t\tif (!Number.isFinite(notifiedAt) || notifiedAt <= 0) {\n\t\t\t\t\t\tlocalStorage.setItem(this.notifiedKey(), String(Date.now()));\n\t\t\t\t\t\treturn;\n\t\t\t\t\t}\n\n\t\t\t\t\tconst fresh = events.filter(e => new Date(e.createdAt).getTime() > notifiedAt);\n\t\t\t\t\tif (fresh.length === 0) {\n\t\t\t\t\t\treturn;\n\t\t\t\t\t}\n\n\t\t\t\t\tconst enabled = await this.notificationsEnabled();\n\t\t\t\t\tif (enabled === null) {\n\t\t\t\t\t\treturn;\n\t\t\t\t\t}\n\t\t\t\t\tif (enabled) {\n\t\t\t\t\t\tfresh.forEach(e => this.showMention(e));\n\t\t\t\t\t}\n\n\t\t\t\t\tconst maxCreated = fresh.reduce((max, e) => Math.max(max, new Date(e.createdAt).getTime()), notifiedAt);\n\t\t\t\t\tlocalStorage.setItem(this.notifiedKey(), String(maxCreated));\n\t\t\t\t},\n\n\t\t\t\t// true/false = the user does/doesn't want browser notifications, null = we\n\t\t\t\t// couldn't find out. Read at delivery time rather than cached at page load:\n\t\t\t\t// the preference can be flipped from the settings modal or another tab.\n\t\t\t\t// Severity and filter-preset scoping are deliberately not consulted - a mention\n\t\t\t\t// is a direct ask from a teammate, not a fired alert.\n\t\t\t\tasync notificationsEnabled() {\n\t\t\t\t\tif (!('Notification' in window) || Notification.permission !== 'granted') {\n\t\t\t\t\t\treturn false;\n\t\t\t\t\t}\n\t\t\t\t\ttry {\n\t\t\t\t\t\tconst response = await fetch('/api/v1/notifications/preferences', { credentials: 'include' });\n\t\t\t\t\t\tif (!response.ok) {\n\t\t\t\t\t\t\treturn null;\n\t\t\t\t\t\t}\n\t\t\t\t\t\tconst result = await response.json();\n\t\t\t\t\t\tif (!result.success || !result.data) {\n\t\t\t\t\t\t\treturn null;\n\t\t\t\t\t\t}\n\t\t\t\t\t\treturn result.data.browser_notifications_enabled === true;\n\t\t\t\t\t} catch (error) {\n\t\t\t\t\t\tconsole.error('Failed to read notification preferences for mentions:', error);\n\t\t\t\t\t\treturn null;\n\t\t\t\t\t}\n\t\t\t\t},\n\n\t\t\t\tshowMention(event) {\n\t\t\t\t\ttry {\n\t\t\t\t\t\tconst notification = new Notification('You were mentioned', {\n\t\t\t\t\t\t\tbody: (event.content || '').slice(0, 200),\n\t\t\t\t\t\t\ticon: '/static/images/info-icon.png',\n\t\t\t\t\t\t\ttag: 'mention-' + event.id\n\t\t\t\t\t\t});\n\n\t\t\t\t\t\tnotification.onclick = () => {\n\t\t\t\t\t\t\twindow.focus();\n\t\t\t\t\t\t\tif (window.location.pathname.startsWith('/dashboard') && window.dashboardInstance?.showAlertDetails) {\n\t\t\t\t\t\t\t\twindow.dashboardInstance.showAlertDetails(event.alertKey);\n\t\t\t\t\t\t\t} else {\n\t\t\t\t\t\t\t\twindow.location.href = '/dashboard/alert/' + event.alertKey;\n\t\t\t\t\t\t\t}\n\t\t\t\t\t\t\tnotification.close();\n\t\t\t\t\t\t};\n\t\t\t\t\t} catch (error) {\n\t\t\t\t\t\tconsole.error('Failed to show mention notification:', error);\n\t\t\t\t\t}\n\t\t\t\t},\n\n\t\t\t\topenMentions() {\n\t\t\t\t\tif (this.userId) {\n\t\t\t\t\t\tlocalStorage.setItem(this.seenKey(), String(Date.now()));\n\t\t\t\t\t}\n\t\t\t\t\tthis.unseenCount = 0;\n\t\t\t\t\twindow.location.href = '/activity?mentions=1';\n\t\t\t\t}\n\t\t\t};\n\t\t}\n\t</script>")
